entries=[
('ارتباط جلسه با دسته‌بندی استخوان‌های جلسهٔ پیش را روشن کنید.','از نمای قدامی به طرفی بروید؛ گونه و فک پایین را با گیجگاهی و آهیانه مرتبط کنید.','نقشهٔ جلسه: گونه و فک پایین استخوان‌های صورت‌اند؛ گیجگاهی و آهیانه در سقف و دیوارهٔ جمجمه بررسی می‌شوند.','در نمای طرفی، از گونه به قوس، سپس به مفصل و استخوان گیجگاهی و در پایان به آهیانه برسید.',3,2,2),
('سطوح و همسایگی‌های گونه مبنای درک کاسهٔ چشم و قوس‌اند.','گونه را در لبهٔ خارجی و تحتانی کاسهٔ چشم و در جلوِ قوس شناسایی کنید.','گونه استخوانی زوج است و در لبهٔ کاسهٔ چشم، برجستگی صورت و قوس گونه‌ای سهم دارد.','در تصویر قدامی، گونه در خارج کاسهٔ چشم است؛ در نمای طرفی، امتداد آن را به عقب دنبال کنید.',3,2,5),
('درز و تکمه‌ها نقاط اتصال بافت نرم و نشانه‌های جهت‌یابی‌اند.','درز فرونتوزایگوماتیک را در لبهٔ خارجی کاسهٔ چشم پیدا و از آن به پایین حرکت کنید.','زائدهٔ پیشانی گونه با زائدهٔ گونه‌ای پیشانی درز فرونتوزایگوماتیک می‌سازد؛ تکمهٔ ویتنال نسبت به این درز پایین‌تر است.','داخل کاسهٔ چشم به سوی بینی و خارج آن به سوی گیجگاه است؛ موقعیت درز را نسبت به لبهٔ خارجی بخوانید.',4,1,5),
('قوس گونه‌ای مرز سطحی مفید میان نواحی گیجگاهی و زیرگیجگاهی است.','دو قطعهٔ سازندهٔ قوس را از گونه در جلو تا گیجگاهی در عقب پیگیری کنید.','قوس حاصل اتصال زائدهٔ گیجگاهیِ گونه و زائدهٔ گونه‌ایِ استخوان گیجگاهی است.','قوس را مانند پلی در کنار جمجمه ببینید؛ حفرهٔ گیجگاهی عمدتاً بالاتر از قوس و زیرگیجگاهی عمیق‌تر و پایین‌تر قرار دارد.',4,2,4),
('تمایز ورودی کاسه‌چشمی و خروجی‌های روی صورت و گیجگاه برای فهم مسیر عصب مفید است.','از شاخهٔ ماگزیلاری به عصب گونه‌ای و سپس دو شاخهٔ انتهایی بروید.','عصب گونه‌ای از شاخهٔ ماگزیلاری عصب سه‌قلو منشأ می‌گیرد و شاخه‌های گونه‌ای‌صورتی و گونه‌ای‌گیجگاهی دارد.','سوراخ کاسه‌چشمی روی سطح چشمی است؛ خروجی گونه‌ای‌صورتی روی سطح چهره‌ای و خروجی گونه‌ای‌گیجگاهی در سطح گیجگاهی قرار می‌گیرد.',5,7,8),
('ارتباط شکل استخوان و بافت نرم در خواندن علائم پس از ضربه مهم است.','لندمارک گونه و لبهٔ کاسهٔ چشم را پیش از نگاه به علامت‌های تصویر مشخص کنید.','صاف شدن برجستگی گونه، تغییر حس و دوبینی از مواردی‌اند که جزوه در بحث ضربه ذکر می‌کند؛ وجود هر نشانه به‌تنهایی تعیین‌کنندهٔ نوع آسیب نیست.','استخوان گونه را مرز خارجی کاسهٔ چشم ببینید؛ جابه‌جایی آن می‌تواند هم نمای صورت و هم روابط کاسهٔ چشم را تغییر دهد.',6,3,4),
('جسم و راموس الگوی کلی مندیبل را می‌سازند و مبنای توصیف سطوح‌اند.','جسم U شکل را از چانه به عقب دنبال کنید و صعود راموس را در دو طرف ببینید.','فک پایین یک جسم تقریباً افقی و دو شاخ صعودی دارد؛ زاویهٔ مندیبل محل گذار میان جسم و شاخ است.','برجستگی چانه و سوراخ منتال در سطح خارجی جسم‌اند؛ حفرهٔ دیگاستریک روی سطح داخلی نزدیک خط وسط قرار می‌گیرد.',7,2,6),
('سوراخ منتال و صفحه‌های استخوانی برای جهت‌یابی دندانی و بی‌حسی مهم‌اند.','در نمای خارجی از چانه به طرف دندان‌های پرمولار رفته و سوراخ منتال را بیابید.','عصب منتال شاخه‌ای از عصب آلوئولار تحتانی است؛ موقعیت سوراخ منتال نسبت به دندان‌ها متغیر است.','باکال رو به گونه و لینگوال رو به زبان است؛ تیغهٔ بین‌دندانی را از تیغهٔ بین‌ریشه‌ای یک دندان چندریشه‌ای جدا کنید.',8,1,7),
('کرونوئید و کندیلار دو کارکرد و دو جهت متفاوت دارند.','در شاخ مندیبل، زائدهٔ قدامی، بریدگی و زائدهٔ خلفی را به ترتیب پیدا کنید.','زائدهٔ کرونوئید در جلو با تاندون تمپورالیس مرتبط است؛ زائدهٔ کندیلار در عقب در مفصل فکی‌گیجگاهی شرکت می‌کند.','بریدگی مندیبل میان دو زائده است؛ مفصل را در بالا و عقب شاخ و نزدیک مجرای شنوایی خارجی ببینید.',9,1,5),
('شناسایی محل شکستگی به ارتباط آن با دندان و مفصل کمک می‌کند.','جسم، زاویه و گردن کندیل را ابتدا روی شکل سالم پیدا و سپس خطوط شکستگی را مقایسه کنید.','جزوه محل‌های جسم، زاویه و گردن کندیل را برای شکستگی مطرح می‌کند؛ الگوی واقعی با محل و جهت ضربه متفاوت است.','زاویه بین جسم و شاخ قرار دارد؛ شکستگی گردن کندیل از شکستگی خود جسم مندیبل جداست.',9,1,5),
('خط مایلوهایوئید دو ناحیهٔ غده‌ای را روی سطح داخلی از هم متمایز می‌کند.','داخل جسم را از خارهای منتال در جلو به خط مایلوهایوئید در عقب دنبال کنید.','حفرهٔ زیرزبانی عمدتاً بالای خط مایلوهایوئید و حفرهٔ زیرآرواره‌ای پایین آن قرار می‌گیرد.','مندیبل را ذهنی از داخل نگاه کنید؛ سمت زبانی بر خلاف سطح چهره‌ای به داخل قوس دندانی می‌نگرد.',11,5,9),
('سوراخ مندیبل، لینگولا و شیار مایلوهایوئید لندمارک‌های سطح داخلی شاخ‌اند.','لینگولا را کنار سوراخ بیابید و شیار مایلوهایوئید را به جلو و پایین دنبال کنید.','عصب و رگ‌های آلوئولار تحتانی وارد سوراخ مندیبل می‌شوند؛ شیار مایلوهایوئید مسیر شاخهٔ مایلوهایوئید را نشان می‌دهد.','در سمت داخلی راموس، سوراخ را ابتدا پیدا کنید؛ زائدهٔ کرونوئید جلوتر و کندیل عقب‌تر است.',12,1,8),
('تغییر ارتفاع بخش آلوئولار و جای نسبی سوراخ منتال را در سنین مختلف مقایسه کنید.','فک نوزاد، فرد دندان‌دار و فک بی‌دندان را در یک جهت نگاه کنار هم قرار دهید.','با از دست رفتن دندان‌ها و تحلیل بخش آلوئولار، سوراخ منتال ممکن است نسبت به لبهٔ فوقانی فک به آن نزدیک‌تر دیده شود.','این تغییر یک رابطهٔ نسبی با لبهٔ استخوان است؛ به معنی حرکت مستقل سوراخ در همهٔ افراد نیست.',13,3,15),
('سوراخ‌های نمای قدامی به نقشه‌برداری اعصاب صورت کمک می‌کنند.','از حاشیهٔ فوقانی کاسهٔ چشم به پایین و سپس سوراخ منتال در فک بروید.','سوراخ یا بریدگی فوق‌چشمی، سوراخ زیرچشمی و سوراخ منتال مسیرهای متفاوت دسته‌های عصبی‌عروقی صورت‌اند.','در شکل، سوراخ زیرچشمی بر ماگزیلا و سوراخ منتال بر مندیبل است؛ استخوان حامل هر سوراخ را جداگانه یادداشت کنید.',16,2,4),
('نشانه‌های قابل لمس را باید به سوراخ استخوانی و شاخهٔ عصبی متناظر وصل کرد.','روی تصویر سطحی ابتدا خط وسط و حاشیهٔ کاسهٔ چشم را تعیین کنید.','فاصله‌های تقریبیِ ذکرشده در جزوه راهنمای سطحی‌اند و در افراد یکسان یا جایگزین تشخیص بالینی نیستند.','برجستگی گونه و چانه را روی صورت بیابید و سپس همان نقطه‌ها را روی شکل استخوانی دنبال کنید.',17,1,4),
('نمای طرفی پنجره‌ای به اجزای گیجگاهی، آهیانه و قوس گونه‌ای است.','استخوان‌ها را با رنگ از پیشانی به عقب و از قوس گونه به سقف جمجمه پیدا کنید.','در نمای طرفی، بخش صدفی گیجگاهی زیر آهیانه قرار می‌گیرد و زائدهٔ گونه‌ای آن در ساخت قوس شرکت دارد.','مجرای شنوایی خارجی یک نشانهٔ مرکزی است؛ قوس جلوتر و زائدهٔ ماستوئید عقب‌تر و پایین‌تر آن دیده می‌شود.',18,3,13),
('موقعیت کندیل نسبت به برجستگی مفصلی کلید درک حرکت و دررفتگی است.','کندیل را از حفرهٔ مندیبولار به جلو روی برجستگی مفصلی دنبال کنید.','در باز شدن دهان، حرکت لولایی و لغزشی مفصل با هم رخ می‌دهند؛ دررفتگی قدامی می‌تواند پس از عبور کندیل از برجستگی ایجاد شود.','در تصویر برشی دو وضعیت بسته و باز را با جای کندیل، دیسک و برجستگی استخوانی مقایسه کنید.',20,2,9),
('شکاف‌ها و زوائد تمپورال را با مجرای گوش و مفصل مرتبط بخوانید.','از حفرهٔ مفصلی به سمت عقب و سپس مجرای گوش و زوائد استایلوئید و ماستوئید حرکت کنید.','سوراخ استایلوماستوئید بین زائده‌های استایلوئید و ماستوئید است و عصب صورتی از آن خارج می‌شود.','در نمای تحتانی، مجرای گوش و حفرهٔ مفصل را لندمارک بگذارید؛ تفاوت شکاف پتروتیمپانیک و سوراخ استایلوماستوئید را حفظ کنید.',25,1,18),
('چهار کنار و زاویهٔ آهیانه، درزهای جمجمه را تشکیل می‌دهند.','آهیانه را بین پیشانی در جلو و پس‌سری در عقب، بالای گیجگاهی ببینید.','کنار قدامی در درز کرونال، کنار فوقانی در درز ساجیتال و کنار خلفی در درز لامبدوئید شرکت می‌کنند.','در نمای فوقانی، دو استخوان آهیانه را دو سوی خط وسط دنبال کنید؛ جلو و عقب را با پیشانی و پس‌سری تعیین کنید.',26,2,12),
('سطح داخلی آهیانه ارتباط استخوان، پرده‌ها و سینوس ساجیتال را نشان می‌دهد.','ناودان خط وسط را پیدا کنید و از آن به حفرات گرانولار و شیار عروق طرفی بروید.','حفرات گرانولار مجاور سینوس ساجیتال و شیار شاخه‌های عروق مننژیال میانی روی سطح داخلی دیده می‌شوند.','نمای داخلی کالواریا را با نمای فوقانی مقایسه کنید؛ جهت نگاه معکوس شده است ولی درز ساجیتال همچنان خط وسط است.',28,1,18),
('مرور، نقشه‌ای مشترک میان استخوان‌ها، سوراخ‌ها و مفصل می‌سازد.','در هر بخش، یک نشانهٔ استخوانی را ابتدا در متن و سپس روی شکل مربوط بیابید.','برای مرور، موارد را به گونه، مندیبل، گیجگاهی و آهیانه تقسیم و نام هر سوراخ یا زائده را به استخوان حامل آن وصل کنید.','در نمای قدامی مسیرهای عصبی سطح صورت را و در نمای طرفی قوس گونه و مفصل را مرور کنید؛ پیش از جابه‌جایی نما جهت نگاه را مشخص کنید.',31,2,48),
]

